html:
{% set plant_print_label = frappe.db.get_single_value("CCPC Approval Settings", "plant_manager_print_label") or "JPR" %}
{% set coo_print_label = frappe.db.get_single_value("CCPC Approval Settings", "coo_print_label") or "JGG" %}
{% set gm_print_label = frappe.db.get_single_value("CCPC Approval Settings", "general_manager_print_label") or "Approved by:" %}
{% set company_logo = frappe.db.get_value("Company", doc.company, "company_logo") if doc.company else None %}

<style>
.print-format {
  page-width: 215.9mm;
  page-height: 330.2mm;
  orientation: Portrait;
  margin-top: 6mm;
  margin-bottom: 6mm;
  margin-left: 6mm;
  margin-right: 6mm;
  padding: 0 !important;
  font-family: Arial, sans-serif;
  color: #000;
}
* { box-sizing: border-box; }
.two-copy-page {
  width: 203.9mm;
  height: 318.2mm;
  margin: 0;
  padding: 0;
  overflow: hidden;
}
.mrs-copy {
  height: 158.1mm;
  padding: 2mm 0 1mm;
  overflow: hidden;
  font-size: 9.5pt;
  line-height: 1.03;
}
.mrs-copy table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.mrs-header td {
  border: 0;
  vertical-align: top;
  padding: 0;
}
.mrs-logo {
  width: 24%;
  height: 11mm;
}
.mrs-logo img {
  max-height: 10.5mm;
  max-width: 31mm;
}
.mrs-title {
  width: 50%;
  text-align: center;
  vertical-align: bottom !important;
  font-size: 12pt;
  padding-top: 3.8mm !important;
  letter-spacing: .15px;
}
.mrs-control {
  width: 26%;
  font-size: 8pt;
  line-height: 1.15;
  text-align: left;
  padding-left: 3mm !important;
}
.meta-row {
  margin: 0.4mm 0 0.7mm;
  display: table;
  width: 100%;
}
.meta-cell {
  display: table-cell;
  vertical-align: bottom;
}
.meta-label { font-weight: 600; }
.underline {
  border-bottom: 0.25mm solid #000;
  display: inline-block;
  min-width: 35mm;
  padding: 0 1mm .3mm;
}
.items th,
.items td {
  border: 0.25mm solid #000;
  padding: 0.45mm 0.65mm;
  vertical-align: middle;
}
.items th {
  text-align: center;
  font-weight: 600;
  font-size: 9pt;
  height: 6.6mm;
}
.items td {
  height: 5.6mm;
  font-size: 9pt;
}
.items .blank-row td { height: 5.6mm; }
.items .center { text-align: center; }
.item-description {
  font-size: 8pt;
  line-height: 1.02;
}
.justification {
  border: 0.25mm solid #000;
  border-top: 0;
  height: 13.5mm;
  padding: 0.6mm 0.8mm;
  overflow: hidden;
}
.justification-title {
  font-weight: 600;
  margin-bottom: 0.5mm;
}
.bottom-grid {
  border: 0.25mm solid #000;
  border-top: 0;
  height: 31.5mm;
}
.bottom-grid td {
  vertical-align: top;
  padding: 0.7mm 1mm;
}
.bottom-left {
  width: 25%;
  border-right: 0.25mm solid #000;
}
.bottom-middle {
  width: 35%;
  border-right: 0.25mm solid #000;
}
.bottom-right { width: 40%; }
.check-row {
  margin-top: 0.8mm;
  line-height: 1.35;
}
.check-box {
  display: inline-block;
  width: 3.1mm;
  height: 3.1mm;
  line-height: 2.8mm;
  text-align: center;
  border: 0.25mm solid #000;
  margin-right: 0.6mm;
  font-size: 8pt;
  vertical-align: middle;
}
.sig-row { margin-top: 0.8mm; }
.sig-line {
  border-bottom: 0.25mm solid #000;
  height: 3.2mm;
  margin: 0 1mm 0.25mm;
}
.sig-caption {
  text-align: center;
  font-size: 8.5pt;
}
.sig-name {
  text-align: center;
  font-size: 8.5pt;
  margin-bottom: .2mm;
  line-height: 1;
}
.authorized-title {
  text-align: center;
  font-weight: 600;
  margin-bottom: 3.2mm;
}
.authorized td {
  padding: 0 1.2mm;
  width: 33.333%;
}
.copy-label {
  margin-top: 0.5mm;
  font-size: 8.5pt;
  font-weight: 600;
}
.small-context {
  font-size: 8pt;
  margin-top: 0.6mm;
  line-height: 1.05;
}
.cut-guide {
  height: 2mm;
  position: relative;
  border-top: 0.25mm dashed #777;
  text-align: center;
  font-size: 7pt;
  color: #666;
  line-height: 2mm;
}
.cut-guide span {
  position: relative;
  top: -1.1mm;
  background: #fff;
  padding: 0 2mm;
}
</style>

{% macro render_mrs_copy(copy_label) %}
<div class="mrs-copy">
  <table class="mrs-header">
    <tr>
      <td class="mrs-logo">
        {% if company_logo %}
          <img src="{{ frappe.get_url(company_logo) }}" alt="CCPC Logo">
        {% elif doc.company %}
          <strong>{{ doc.company }}</strong>
        {% endif %}
      </td>
      <td class="mrs-title">MATERIAL REQUISITION SLIP</td>
      <td class="mrs-control">
        <div>CCPC PUR-F-001</div>
        <div>Revision No.00</div>
        <div>Effectivity Date: August 25, 2023</div>
      </td>
    </tr>
  </table>

  <div class="meta-row">
    <div class="meta-cell" style="width:34%;">
      <span class="meta-label">Date:</span>
      <span class="underline">{{ frappe.utils.formatdate(doc.request_date, "dd MMM yyyy") if doc.request_date else "" }}</span>
    </div>
    <div class="meta-cell" style="width:32%;"></div>
    <div class="meta-cell" style="width:34%; text-align:right;">
      <span class="meta-label">MRS#</span>
      <span class="underline" style="min-width:39mm;">{{ doc.name }}</span>
    </div>
  </div>

  <table class="items">
    <thead>
      <tr>
        <th style="width:4%;">Item<br>#</th>
        <th style="width:40%;">DESCRIPTION</th>
        <th style="width:7%;">Qty</th>
        <th style="width:9%;">Unit</th>
        <th style="width:12%;">Price</th>
        <th style="width:13%;">Date Needed</th>
        <th style="width:15%;">Remarks</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
      <tr>
        <td class="center">{{ row.idx }}</td>
        <td>
          {{ row.item_name or row.item_code or "" }}
          {% if row.description and row.description != row.item_name %}
            <div class="item-description">{{ row.description }}</div>
          {% endif %}
        </td>
        <td class="center">{{ row.get_formatted("requested_qty", doc) }}</td>
        <td class="center">{{ row.uom or "" }}</td>
        <td>&nbsp;</td>
        <td class="center">{{ frappe.utils.formatdate(row.date_needed, "dd MMM yyyy") if row.date_needed else "" }}</td>
        <td>{{ row.remarks or "" }}</td>
      </tr>
      {% endfor %}
      {% set blank_rows = 8 - (doc.items|length) %}
      {% if blank_rows > 0 %}
        {% for i in range(blank_rows) %}
        <tr class="blank-row">
          <td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td><td></td>
        </tr>
        {% endfor %}
      {% endif %}
    </tbody>
  </table>

  <div class="justification">
    <div class="justification-title">Justification</div>
    <div>{{ doc.justification or "" }}</div>
  </div>

  <table class="bottom-grid">
    <tr>
      <td class="bottom-left">
        <div class="sig-name">{{ doc.use_department or "" }}</div>
        <div class="sig-line" style="margin-top:0.8mm;"></div>
        <div class="sig-caption">Dept. End User</div>

        <div class="check-row">
          <span class="check-box">{% if doc.request_category == "Maintenance" %}✓{% endif %}</span> Maintenance
          &nbsp;
          <span class="check-box">{% if doc.request_category == "Others" %}✓{% endif %}</span> Others
          <br>
          <span class="check-box">{% if doc.request_category == "Project" %}✓{% endif %}</span> Project
        </div>

        {% if doc.equipment or doc.work_request or doc.job_order or doc.physical_location %}
        <div class="small-context">
          {% if doc.equipment %}<div>Equipment: {{ doc.equipment }}</div>{% endif %}
          {% if doc.work_request %}<div>Work Request: {{ doc.work_request }}</div>{% endif %}
          {% if doc.job_order %}<div>Job Order: {{ doc.job_order }}</div>{% endif %}
          {% if doc.physical_location %}<div>Location: {{ doc.physical_location }}</div>{% endif %}
        </div>
        {% endif %}
      </td>

      <td class="bottom-middle">
        <div class="sig-row">
          <div class="sig-name">{{ doc.prepared_by_name or "" }}</div>
          <div class="sig-line"></div>
          <div class="sig-caption">Prepared by</div>
        </div>

        <div class="sig-row" style="margin-top:1.2mm;">
          <div><strong>Verified / Recommended by:</strong></div>
          <div class="sig-name">
            {{ doc.requesting_department_manager_name or "" }}
            {% if doc.use_department_manager_name and doc.use_department_manager_name != doc.requesting_department_manager_name %}
              <br>Use Dept. Manager: {{ doc.use_department_manager_name }}
            {% endif %}
          </div>
          <div class="sig-line"></div>
          <div class="sig-caption">Department Manager</div>
        </div>
      </td>

      <td class="bottom-right">
        <div class="authorized-title">Authorized By:</div>
        <table class="authorized">
          <tr>
            <td>
              <div class="sig-line"></div>
              <div class="sig-caption">{{ plant_print_label }}</div>
            </td>
            <td>
              <div class="sig-line"></div>
              <div class="sig-caption">{{ coo_print_label }}</div>
            </td>
            <td>
              <div class="sig-line"></div>
              <div class="sig-caption">{{ gm_print_label }}</div>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>

  <div class="copy-label">{{ copy_label }}</div>
</div>
{% endmacro %}

<div class="two-copy-page">
  {{ render_mrs_copy("Original Copy - Purchasing") }}
  <div class="cut-guide"><span>CUT HERE</span></div>
  {{ render_mrs_copy("Duplicate - Stockroom") }}
</div>
